from src.dp_advanced import coin_change, lis, longest_common_subsequence


def test_coin_change_basic():
    assert coin_change([1, 5, 10, 25], 36) == 3  # 25+10+1
    assert coin_change([1, 5, 10, 25], 0) == 0


def test_coin_change_impossible():
    assert coin_change([2], 3) == -1


def test_lis_basic():
    assert lis([10, 9, 2, 5, 3, 7, 101, 18]) == 4  # 2,3,7,18 or 2,5,7,18
    assert lis([0, 1, 0, 3, 2, 3]) == 4


def test_lis_all_same():
    assert lis([5, 5, 5, 5]) == 1


def test_lcs_basic():
    assert longest_common_subsequence("abcde", "ace") == 3
    assert longest_common_subsequence("abc", "abc") == 3
    assert longest_common_subsequence("abc", "def") == 0
